class MainActivity : ComponentActivity() {
    private val widgetAction = mutableStateOf<String?>(null)
    private var nativeStateForLifecycle: JSONObject? = null
    private var nativeRepoForLifecycle: HouseholdRepository? = null
    override fun onNewIntent(intent: Intent) { super.onNewIntent(intent); setIntent(intent); widgetAction.value=intent.getStringExtra(BetaWidgetProvider.EXTRA_BETA_ACTION) }
    override fun onStop() { nativeStateForLifecycle?.let { nativeRepoForLifecycle?.autoBackup(it) }; super.onStop() }
    override fun onCreate(savedInstanceState: Bundle?) {
        super.onCreate(savedInstanceState)
        widgetAction.value=intent?.getStringExtra(BetaWidgetProvider.EXTRA_BETA_ACTION)
        setContent {
            val activity=this@MainActivity
            val themeRepo=remember{HouseholdRepository(activity)}
            var themeRevision by remember{mutableStateOf(0)}
            val choice=remember(themeRevision){themeRepo.getSetting("household-theme")?.takeIf{it in setOf("light","dark","system")} ?: "system"}
            val systemDark=androidx.compose.foundation.isSystemInDarkTheme()
            val dark=choice=="dark" || (choice=="system" && systemDark)
            MaterialTheme(
                colorScheme = if (dark) darkColorScheme(primary=Color(0xFF5B9CFF), background=Color(0xFF0F1013), surface=Color(0xFF1E1F24), onBackground=Color(0xFFF2F2F4), onSurface=Color(0xFFF2F2F4))
                else lightColorScheme(primary=Blue, background=Paper, surface=SurfaceSolid, onBackground=Ink, onSurface=Ink)
            ) { CompositionLocalProvider(LocalAppDark provides dark) { NativeApp(onThemeChanged={themeRevision++},initialWidgetAction=widgetAction.value,onWidgetActionConsumed={widgetAction.value=null}) } }
        }
    }
}

private class HouseholdRepository(private val activity: Activity) {
    private val store = NativeKeyValueStore.getInstance(activity)
    private val key = "household-data-v8"
    fun load(): JSONObject = runCatching { JSONObject(store.getItem(key) ?: "{}") }.getOrDefault(JSONObject())
    fun save(state: JSONObject) = store.setItem(key, state.toString())
    fun getSetting(name:String):String? = store.getItem(name)
    fun setSetting(name:String,value:String) = store.setItem(name,value)
    fun removeSetting(name:String) = store.removeItem(name)
    fun autoBackup(state:JSONObject){if(getSetting("haushaltsbuch-autobackup-enabled")!="1")return;val raw=getSetting("haushaltsbuch-autobackup-uri")?:return;runCatching{val tree=DocumentFile.fromTreeUri(activity,Uri.parse(raw))?:return;val file=tree.findFile("haushaltsbuch-auto-backup.csv")?:tree.createFile("text/csv","haushaltsbuch-auto-backup.csv")?:return;activity.contentResolver.openOutputStream(file.uri,"wt")?.bufferedWriter()?.use{it.write(buildBackup(state))}}}
    fun buildBackup(state:JSONObject):String{val tables=listOf("income" to listOf("id","name","amount"),"fixedExpenses" to listOf("id","name","amount","icon"),"openInvoices" to listOf("id","name","amount","dueDate","paid","paidDate"),"variableCosts" to listOf("id","name","monthlyAmount","actualAmount","interval","dueMonth","dueYear"),"variableContributions" to listOf("id","date","amount","note"),"variablePayments" to listOf("id","itemId","itemName","date","amount"),"loans" to listOf("id","name","originalAmount","remainingBalance","monthlyPayment","totalTermMonths","paidOffDate","carryoverPct","totalWithInterest","monthlyRate","lastReconciledBalance","lastReconciledDate"),"loanPayments" to listOf("id","loanId","date","amount","type"),"savings" to listOf("id","date","amount","type","comment"),"cars" to listOf("id","name"),"fuelLogs" to listOf("id","carId","liters","pricePerLiter","date"),"betaEntries" to listOf("id","type","title","date","amount","category","recurring","reconciled","isRecurringTemplate","recurrencePeriod","recurrenceEnd","recurringGroupId"));fun esc(v:Any?):String{val s=if(v==null||v==JSONObject.NULL)"" else v.toString();return if(s.any{it==','||it=='"'||it=='\n'}) "\""+s.replace("\"","\"\"")+"\"" else s};val out=mutableListOf<String>();tables.forEach{(name,cols)->val lines=mutableListOf("# TABLE:$name",cols.joinToString(","));array(state,name).objects().forEach{o->lines+=cols.joinToString(","){esc(o.opt(it))}};out+=lines.joinToString("\n")};out+=listOf("# TABLE:settings","amount",esc(state.optDouble("potCarryover",0.0))).joinToString("\n");val vis=getSetting("household-tab-visibility")?:"{}";val extra=getSetting("household-tilgung-extra")?:"0";val current=getSetting("household-tilgung-current-month")?:"";out+=listOf("# TABLE:appSettings","tabVisibilityJson,tilgungExtra,tilgungCurrentMonth",listOf(esc(vis),esc(extra),esc(current)).joinToString(",")).joinToString("\n");return out.joinToString("\n\n")}
    fun restoreBackup(text:String):JSONObject{
        fun rows(s:String):List<List<String>>{val out=mutableListOf<List<String>>();var row=mutableListOf<String>();val field=StringBuilder();var quoted=false;var i=0;while(i<s.length){val ch=s[i];if(quoted){if(ch=='"'&&i+1<s.length&&s[i+1]=='"'){field.append('"');i++}else if(ch=='"')quoted=false else field.append(ch)}else when(ch){'"'->quoted=true;','->{row.add(field.toString());field.clear()};'\n'->{row.add(field.toString());field.clear();out.add(row);row=mutableListOf()};'\r'->{};else->field.append(ch)};i++};if(field.isNotEmpty()||row.isNotEmpty()){row.add(field.toString());out.add(row)};return out}
        val result=JSONObject();listOf("income","fixedExpenses","openInvoices","variableCosts","variableContributions","variablePayments","loans","loanPayments","savings","cars","fuelLogs","betaEntries").forEach{result.put(it,JSONArray())};result.put("potCarryover",0.0)
        var table:String?=null;var cols:List<String>?=null
        rows(text).forEach{r->if(r.isEmpty())return@forEach;val first=r[0].trim();if(first.startsWith("# TABLE:")){table=first.removePrefix("# TABLE:").trim();cols=null;return@forEach};if(r.all{it.isBlank()})return@forEach;if(cols==null){cols=r.map{it.trim()};return@forEach};val map=cols!!.mapIndexed{i,k->k to r.getOrElse(i){""}}.toMap();when(table){"settings"->result.put("potCarryover",map["amount"]?.toDoubleOrNull()?:0.0);"appSettings"->{map["tabVisibilityJson"]?.takeIf{it.isNotBlank()}?.let{setSetting("household-tab-visibility",it)};map["tilgungExtra"]?.takeIf{it.isNotBlank()}?.let{setSetting("household-tilgung-extra",it)};map["tilgungCurrentMonth"]?.takeIf{it.isNotBlank()}?.let{setSetting("household-tilgung-current-month",it)}};else->{val a=result.optJSONArray(table?:"")?:return@forEach;val o=JSONObject();map.forEach{(k,v)->val value:Any=when{k in setOf("amount","monthlyAmount","actualAmount","originalAmount","remainingBalance","monthlyPayment","totalWithInterest","monthlyRate","lastReconciledBalance","liters","pricePerLiter")->v.toDoubleOrNull()?:0.0;k in setOf("dueMonth","dueYear","totalTermMonths","carryoverPct")->v.toIntOrNull()?:JSONObject.NULL;k in setOf("paid","recurring","reconciled","isRecurringTemplate")->v=="true"||v=="1";else->if(v.isBlank())JSONObject.NULL else v};o.put(k,value)};if(table=="variableCosts"&&!o.has("interval"))o.put("interval","jaehrlich");if(table=="loanPayments"&&(o.isNull("type")||o.optString("type").isBlank()))o.put("type","payment");a.put(o)}}}
        save(result);return result
    }
    fun array(state: JSONObject, name: String): JSONArray = state.optJSONArray(name) ?: JSONArray().also { state.put(name, it) }
}

private fun JSONArray.objects(): List<JSONObject> = (0 until length()).mapNotNull { optJSONObject(it) }
private fun money(v: Double): String = NumberFormat.getCurrencyInstance(Locale.GERMANY).format(v)
private fun sum(a: JSONArray, field: String, predicate: (JSONObject)->Boolean = { true }): Double = a.objects().filter(predicate).sumOf { it.optDouble(field, 0.0) }
private enum class Tab(val label:String){BALANCE("Kontostand"),BOOKINGS("Buchungen"),VARIABLE("Variable Kosten"),LOANS("Kredite"),FUEL("Tanken")}

@Composable private fun NativeApp(onThemeChanged:()->Unit,initialWidgetAction:String?,onWidgetActionConsumed:()->Unit){
    val activity=androidx.compose.ui.platform.LocalContext.current as Activity
    val repo=remember{HouseholdRepository(activity)}
    SideEffect { if(activity is MainActivity){activity.nativeStateForLifecycle=state;activity.nativeRepoForLifecycle=repo} }
    var state by remember{mutableStateOf(repo.load())};var tab by remember{mutableStateOf(Tab.BALANCE)};var visibilityRevision by remember{mutableStateOf(0)};val tabVisibility=remember(visibilityRevision){runCatching{JSONObject(repo.getSetting("household-tab-visibility")?:"{}")}.getOrDefault(JSONObject())};val visibleTabs=Tab.entries.filter{t->val k=when(t){Tab.BALANCE->"beta";Tab.BOOKINGS->"buchungen";Tab.VARIABLE->"variabel";Tab.LOANS->"kredite";Tab.FUEL->"tanken"};if(tabVisibility.has(k))tabVisibility.optBoolean(k,true) else true}.ifEmpty{listOf(Tab.BALANCE)};LaunchedEffect(visibleTabs){if(tab !in visibleTabs)tab=visibleTabs.first()};var addBeta by remember{mutableStateOf(false)};var betaInitialType by remember{mutableStateOf<String?>(null)};var addForm by remember{mutableStateOf<String?>(null)};var fabOpen by remember{mutableStateOf(false)};var settings by remember{mutableStateOf(false)};var month by remember{mutableStateOf(YearMonth.now())}
    fun persist(){repo.save(state);repo.autoBackup(state);state=JSONObject(state.toString())}
    fun updateWidgetBalance(){val entries=repo.array(state,"betaEntries").objects();val balance=entries.sumOf{if(it.optString("type")=="income"||it.optString("type")=="einnahme")it.optDouble("amount") else -it.optDouble("amount")};activity.getSharedPreferences(BetaWidgetProvider.PREFS_NAME,Context.MODE_PRIVATE).edit().putString(BetaWidgetProvider.KEY_BALANCE,money(balance)).putBoolean(BetaWidgetProvider.KEY_POSITIVE,balance>=0).apply();BetaWidgetProvider.updateAll(activity);if(repo.getSetting("household-kontostand-notification-enabled")=="1"){runCatching{ContextCompat.startForegroundService(activity,Intent(activity,KontostandForegroundService::class.java).putExtra(KontostandForegroundService.EXTRA_BALANCE_TEXT,money(balance)).putExtra(KontostandForegroundService.EXTRA_IS_POSITIVE,balance>=0))}}}
    LaunchedEffect(state.toString()){updateWidgetBalance()}
    LaunchedEffect(initialWidgetAction){when(initialWidgetAction){BetaWidgetProvider.ACTION_ADD_EINNAHME->{tab=Tab.BALANCE;betaInitialType="income";addBeta=true};BetaWidgetProvider.ACTION_ADD_AUSGABE->{tab=Tab.BALANCE;betaInitialType="expense";addBeta=true};BetaWidgetProvider.ACTION_OPEN->{tab=Tab.BALANCE}};if(initialWidgetAction!=null)onWidgetActionConsumed()}
    Scaffold(
        topBar={Surface(color=MaterialTheme.colorScheme.background.copy(alpha=.92f)){Column(Modifier.fillMaxWidth().padding(horizontal=20.dp,vertical=10.dp)){Row(Modifier.fillMaxWidth(),verticalAlignment=Alignment.CenterVertically){Text("Haushaltsbuch",fontSize=32.sp,fontWeight=FontWeight.ExtraBold,letterSpacing=(-.6).sp);Text("+",fontSize=32.sp,fontWeight=FontWeight.ExtraBold,color=MaterialTheme.colorScheme.primary);Spacer(Modifier.weight(1f));Surface(shape=CircleShape,color=MaterialTheme.colorScheme.surface,modifier=Modifier.size(38.dp).clickable{settings=true}){Box(contentAlignment=Alignment.Center){SettingsGearIcon(MaterialTheme.colorScheme.onSurfaceVariant)}}}}}},
        bottomBar={Surface(tonalElevation=3.dp,shape=RoundedCornerShape(26.dp),modifier=Modifier.padding(horizontal=6.dp,vertical=4.dp)){Row(Modifier.fillMaxWidth().padding(vertical=6.dp)){visibleTabs.forEach{t->Column(Modifier.weight(1f).padding(vertical=6.dp).clickable{tab=t},horizontalAlignment=Alignment.CenterHorizontally){OriginalTabIcon(t,if(tab==t)MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,tab==t);Text(t.label,fontSize=10.5.sp,maxLines=1,color=if(tab==t)MaterialTheme.colorScheme.primary else MaterialTheme.colorScheme.onSurfaceVariant,fontWeight=FontWeight.Bold)}}}}},
        floatingActionButton={Box(contentAlignment=Alignment.BottomEnd){if(fabOpen){Box(Modifier.fillMaxSize().background(Color.Black.copy(alpha=.4f)).clickable{fabOpen=false});Column(horizontalAlignment=Alignment.End,verticalArrangement=Arrangement.spacedBy(14.dp),modifier=Modifier.padding(bottom=76.dp)){fabOptions(tab).forEach{opt->Row(verticalAlignment=Alignment.CenterVertically,horizontalArrangement=Arrangement.spacedBy(10.dp)){Surface(shape=RoundedCornerShape(12.dp),color=MaterialTheme.colorScheme.surface){Text(opt,Modifier.padding(horizontal=13.dp,vertical=8.dp),fontSize=13.sp,fontWeight=FontWeight.Bold)};Surface(shape=CircleShape,color=fabOptionColor(opt),modifier=Modifier.size(46.dp).clickable{if(opt=="Neuer Eintrag"){betaInitialType=null;addBeta=true}else addForm=opt;fabOpen=false}){Box(contentAlignment=Alignment.Center){Text("+",fontSize=22.sp,color=Color.White)}}}}}};Surface(shape=CircleShape,color=MaterialTheme.colorScheme.primary.copy(alpha=.80f),modifier=Modifier.size(60.dp).clickable{fabOpen=!fabOpen},shadowElevation=8.dp){Box(contentAlignment=Alignment.Center){Text(if(fabOpen)"×" else "+",fontSize=30.sp,color=Color.White)}}}}
    ){pad->Box(Modifier.padding(pad).fillMaxSize().background(MaterialTheme.colorScheme.background)){when(tab){Tab.BALANCE->BalanceScreen(state,repo,month,{month=month.minusMonths(1)},{month=month.plusMonths(1)});Tab.BOOKINGS->BookingsScreen(state,repo);Tab.VARIABLE->VariableScreen(state,repo);Tab.LOANS->LoansScreen(state,repo);Tab.FUEL->FuelScreen(state,repo)}}}
    if(settings)SettingsDialog(state,repo,{settings=false},onThemeChanged,{visibilityRevision++},{restored->state=JSONObject(restored.toString());visibilityRevision++;updateWidgetBalance()})
    addForm?.let{QuickAddForm(it,state,repo,{addForm=null}){persist();addForm=null}}\n    if(addBeta)BetaEntryDialog(betaInitialType,{addBeta=false;betaInitialType=null}){type,title,date,amount,category->repo.array(state,"betaEntries").put(JSONObject().put("id",UUID.randomUUID().toString()).put("type",type).put("title",title).put("date",date).put("amount",amount).put("category",category).put("recurring",false).put("reconciled",false));persist();addBeta=false}
}

private fun fabOptions(tab:Tab):List<String> = when(tab){Tab.BALANCE->listOf("Neuer Eintrag");Tab.BOOKINGS->listOf("Offene Rechnung","Einnahme","Fixkosten");Tab.VARIABLE->listOf("Einzahlung in den Spartopf","Variable Kostenart");Tab.LOANS->listOf("Kredit");Tab.FUEL->listOf("Tankvorgang","Auto hinzufügen")}
private fun fabOptionColor(label:String):Color{val dark=LocalAppDark.current;return when(label){"Einnahme","Einzahlung in den Spartopf"->appGreen(dark);"Offene Rechnung"->if(dark)Color(0xFFFFB03F) else Color(0xFFFF9F0A);"Kredit"->appRed(dark);"Tankvorgang","Auto hinzufügen"->if(dark)Color(0xFF9CA3AF) else Color(0xFF6B7280);else->appBlue(dark)}}

